import type { LearningEntry } from './neurodevelopment';
type Longform = Pick<LearningEntry, 'intro' | 'takeaways' | 'sections'>;

export const longform: Record<string, Longform> = {
  'assessment-visit-planner': {
    intro: ['A developmental appointment can cover years of history in a short conversation. It is easy to remember a key question only after leaving, or to spend most of the visit trying to explain a broad concern such as “school is difficult”. This planner helps turn that concern into a few useful examples.', 'Use the guidance below to prepare, then print the blank worksheet. You do not need to complete every item or know which diagnosis to ask about. The most valuable preparation is an honest description of the child’s strengths, difficulties and everyday context.'],
    takeaways: ['Bring examples rather than a proposed diagnosis.', 'Include strengths, languages and the child’s own perspective.', 'Leave with a named next step and a review plan.'],
    sections: [
      { title: 'Before the visit: choose your main question', text: 'Write the concern in one sentence, then add one recent example. “My child struggles with transitions” becomes more useful when followed by “Leaving the playground takes about 20 minutes and often ends in tears, even after a verbal warning”. Describe the setting and what adults tried, without assigning blame.', paragraphs: ['Choose up to three questions you most want answered. Separate an urgent medical change from a longer-standing developmental concern. If there has been loss of skills, a seizure, sudden weakness or a child who is acutely unwell, seek appropriate medical advice promptly rather than waiting to finish this planner.'] },
      { title: 'Bring a balanced picture of the child', text: 'Include enjoyable activities, successful situations and preferred ways of communicating. Mention the languages used by family members and school. A child may show different abilities with different people, so bring both accounts rather than deciding that one must be wrong.', paragraphs: ['List previous assessments, hearing or vision information if available, and current medicines and supplements. Product labels can prevent confusion over ingredients. Do not pay for a new test package just to arrive “fully prepared”; ask the clinician which investigations, if any, are needed. A concise summary is usually more useful than a large folder with no explanation of what matters.'], example: { title: 'Illustrative completed note', text: 'Main question: “How can school instructions be easier to follow?” Example: “P. manages one step at home but loses track of three-step spoken instructions in class.” Strength: “Enjoys drawing and follows picture sequences for craft.” Family goal: “Start the first classroom task with less distress.”' } },
      { title: 'During the appointment: clarify the recommendation', text: 'Ask what each suggested assessment or therapy is intended to answer or improve. If a term is unfamiliar, request an everyday example. Ask whether recommendations are urgent, optional or dependent on another result. If the plan is more than the family can currently manage, say so; priorities should be discussed openly.', paragraphs: ['Where possible, include the child’s views and communication preferences. Ask how information will be shared with school and what consent is needed. A report can contain sensitive family or medical information that is not necessary for every teacher. It may be more appropriate to share the relevant support recommendations rather than the entire document.'] },
      { title: 'After the visit: turn advice into a next step', text: 'Record who will arrange each referral, how results will be communicated and when to review. For a home or school strategy, agree a concrete goal and how you will notice improvement or increased distress. For medicine, follow the prescriber’s instructions and clarify how to report concerns.', paragraphs: ['Keep the completed sheet somewhere private. Bring it back to the next visit and mark what happened: completed, waiting, no longer needed or unclear. The sheet is a conversation aid, not a diagnostic test, and it should reduce the family’s administrative burden rather than create another task they must perform perfectly.'] },
    ],
  },
  'daily-comfort-diary': {
    intro: ['When sleep, eating and distress seem to change together, memory can blur the sequence. A brief diary helps a family describe what happened without having to decide in advance why it happened. It can be particularly useful when a child communicates discomfort through gestures, changes in activity or behaviour.', 'Use one printed sheet for a day and repeat for a few ordinary days if useful. This is not a food challenge, an elimination-diet protocol or a symptom score. Its purpose is to support a conversation with a clinician, dietitian or therapist.'],
    takeaways: ['Record ordinary routines, including days that go well.', 'Separate what you observed from what you think caused it.', 'Do not change medicines or restrict foods to test a theory through this diary.'],
    sections: [
      { title: 'What to record—and what to leave out', text: 'Note bedtime and waking, meals and drinks accepted, bowel comfort, relevant medicines and changes in routine. Describe the child’s communication as accurately as possible: “pointed to stomach” is more useful than “gut inflammation”. A short note about the environment can matter as much as a food entry.', paragraphs: ['Avoid trying to count every movement, expression or mouthful. The diary should be sustainable and should not make the child feel watched throughout the day. If nothing unusual happened, record that too. A diary containing only difficult episodes can give an incomplete impression of the week.'] },
      { title: 'A worked example of a neutral entry', text: 'Suppose a child becomes upset after lunch. The interpretation might be “dairy caused a meltdown”, but the observation could be: “Ate rice and curd at 1 pm. Fire alarm test at 1:20 pm. Cried and covered ears; settled in the quiet room after 15 minutes.” The second account preserves several possible explanations.', paragraphs: ['Another entry might say: “Woke three times overnight; hard stool in the morning; declined breakfast; said ‘tummy hurts’.” That gives the clinician a pattern to investigate without claiming that sleep, food or behaviour caused the others. Record a change recommended by a clinician along with its start date, but avoid making additional changes solely to create an experiment.'], table: { caption: 'Observation and interpretation are different', headings: ['Less useful', 'More useful'], rows: [['Bad day', 'Needed a quiet break after assembly; joined art later'], ['Reacted to gluten', 'Stomach pain reported after lunch; similar pain also occurred before breakfast'], ['Medicine failed', 'Difficulty falling asleep on three nights; dose taken as prescribed; school trip this week']] } },
      { title: 'When recording should give way to seeking help', text: 'Do not delay care to obtain a complete week of notes. Persistent vomiting, blood in stool, dehydration, severe pain, concerning weight loss or a child who is markedly unwell needs medical advice. New neurological symptoms or loss of skills should be reported promptly.', paragraphs: ['Likewise, do not explain a new rash, pain or worsening function as beneficial detoxification. If a symptom appears after a treatment change, tell the prescriber or clinician what changed and when. The diary is supporting information, not permission to continue a concerning intervention.'] },
      { title: 'Review the pattern with a clear question', text: 'At the end, choose the question the diary helps you ask. For example: “Could constipation be contributing to mealtime distress?” or “Does the sleep pattern need assessment?” Ask which findings need investigation and which everyday adjustments are reasonable.', paragraphs: ['Keep completed sheets private. Share only what is relevant with school or other professionals, and include the child in that decision where appropriate. Stop the diary when it has answered its purpose; long-term surveillance is not automatically more useful than a short, well-described period. The website does not collect your written entries.'] },
    ],
  },
  'school-support-planner': {
    intro: ['“Needs to concentrate” is a concern, but it is not yet a support plan. A useful home–school plan identifies a particular situation, explains the barrier and sets out what adults will do differently. It also includes the child’s experience: apparent compliance is not the same as comfort, understanding or participation.', 'This resource helps families and teachers agree a small, reviewable plan. It is not a formal educational assessment or a statement of legal entitlement. Use it alongside professional recommendations and the school’s own procedures.'],
    takeaways: ['Choose one situation and one meaningful participation goal.', 'Write the support adults will provide, not only the behaviour expected of the child.', 'Review benefit and distress, including the child’s perspective.'],
    sections: [
      { title: 'Define a situation rather than labelling a child', text: 'Replace “does not cooperate” with a description: “When the class moves from lunch to writing, J. remains by the lunch area and becomes upset when hurried.” This allows adults to ask whether the difficulty involves transition, understanding, fatigue, sensory load or something else.', paragraphs: ['Ask the child what would help, using their preferred communication method. If they cannot explain verbally, consider their gestures, choices and consistent responses without pretending those observations prove an internal state. Record a strength or interest too: a support plan should describe the whole learner, not only the problem adults want to remove.'] },
      { title: 'Choose an adjustment that matches the barrier', text: 'If spoken instructions are difficult to retain, a visible sequence may help. If the room is overwhelming, a quieter place or an agreed break may be worth discussing. If a transition is unpredictable, advance information and a consistent cue may make it easier. These are examples, not a universal package.', table: { caption: 'From a broad concern to a specific support', headings: ['Concern', 'Possible adjustment to discuss', 'What to observe'], rows: [['Loses track of instructions', 'One step at a time plus a visible reminder', 'Can the child start with fewer repetitions?'], ['Distress during transitions', 'Preview the next activity and use an agreed cue', 'Does the transition require less distress or recovery?'], ['Difficulty asking for a break', 'Agree a spoken, picture or gesture-based request', 'Can the child access the break when needed?'], ['Overload in a busy area', 'Discuss a quieter option without social exclusion', 'Can the child participate more comfortably?']] }, paragraphs: ['Make the adult responsibility explicit. “Will behave during assembly” gives the child a demand but gives adults no action. “Teacher offers the agreed quieter seating option and checks whether it helps” describes something that can actually be implemented and reviewed.'] },
      { title: 'Write a goal that is meaningful and achievable', text: 'Choose a goal related to access or participation, such as beginning a task with the agreed support, communicating a need or joining a preferred group activity. Avoid making harmless movement, forced eye contact or appearing indistinguishable from peers the goal.', paragraphs: ['A goal can be specific without becoming a rigid performance target. For example, the team might observe whether the child uses a break request and can return when ready. If using the request leads to punishment or refusal, the communication system will not be trustworthy. Discuss what adults will do when the child is overwhelmed before that situation happens.'], example: { title: 'Illustrative shared plan', text: 'Situation: moving from play to handwriting. Support: a picture of the next activity, a short warning and a clear first step. Goal: begin with less distress. Review: family and teacher compare brief observations after an agreed period, including whether the child finds the support helpful.' } },
      { title: 'Review and share information proportionately', text: 'Agree who will communicate, how often and which details are useful. A short factual update may be enough; families and teachers do not need to produce lengthy daily reports. Obtain appropriate consent before sharing medical or assessment information, and avoid circulating sensitive reports in group chats.', paragraphs: ['At review, ask whether the adjustment was actually available and used before concluding that it failed. Look for benefit, burden and unintended effects. A strategy that increases distress should be reconsidered. If concerns persist, the team can discuss further assessment or professional input. A diagnosis may help explain needs, but families can begin a practical conversation with school while assessment is ongoing.'] },
    ],
  },
  'autism-gut-health-and-diets': {
    intro: ['A child accepts only a handful of foods, struggles with constipation and becomes distressed around meals. The family is then told that gluten, dairy, “leaky gut” or a particular bacterium explains everything. Removing foods can feel like a practical action when the underlying problem is still unclear.', 'Gut symptoms deserve attention. So do feeding difficulties, nutritional adequacy and the child’s experience of eating. But treating discomfort is a different goal from claiming that a diet treats autism itself. This guide explains that difference, translates common microbiome claims and offers a structured way to bring useful information to a clinical or dietetic appointment.'],
    takeaways: ['Investigate pain, constipation and feeding difficulties on their own merits.', 'Dietary restriction needs a specific reason and a plan to protect nutrition.', 'A diary can identify questions; it cannot diagnose food intolerance or an autism subtype.'],
    sections: [
      { title: 'Start with the symptom, not a theory about the gut', text: 'Describe the problem in everyday terms. Is stool hard or painful to pass? Does the child avoid the toilet, eat less, wake with discomfort or accept fewer foods than before? Can they chew and swallow comfortably? A change in behaviour may be a way of communicating pain, especially when describing bodily sensations is difficult.', paragraphs: ['Avoid assuming that all distress is “just autism”, but also avoid assuming that every difficult day comes from the gut. Sleep, demands, sensory experience, illness and communication can all matter. Seek prompt medical care for persistent vomiting, blood in stool, dehydration, severe pain or concerning weight loss. A food experiment is not the first response to an acutely unwell child.'] },
      { title: 'Constipation can become a self-reinforcing problem', text: 'A painful bowel movement can lead a child to delay going again. Holding stool can then make the next bowel movement harder and more uncomfortable. Families may notice withholding movements, fear of the toilet or soiling and not immediately recognize constipation as a possibility.', paragraphs: ['Assessment should consider the history, medicines, growth and any warning features. The American College of Gastroenterology describes behavioural and medical elements of management; a clinician should tailor the plan. Simply telling a child to try harder, or repeatedly changing supplements, may miss the cycle of pain and avoidance. Ask for clear instructions, what improvement should look like and when to return if the plan is not working.'], source: 'constipation' },
      { title: 'Selective eating: look beyond willingness', text: 'A narrow food range can involve texture, smell, temperature, predictability, pain, oral skills or anxiety around unfamiliar food. “Picky eating” is a description, not an explanation. Record which foods are accepted reliably and what characteristics they share. A child who accepts crunchy foods but struggles with mixed textures presents a different question from one whose intake has suddenly fallen.', paragraphs: ['A feeding assessment may need input from medical, dietetic and developmental professionals depending on the concern. The aim is adequate nutrition and a less distressing eating experience, not winning a contest over a bite. Discuss small, realistic changes with the team. Avoid withdrawing all familiar foods to force acceptance; a child still needs dependable access to nutrition while new strategies are explored.'], example: { title: 'Illustrative observation', text: '“S. eats plain rice and curd separately but refuses them mixed. The same foods are accepted at grandmother’s house when served in separate bowls.” This suggests a useful question about presentation and predictability. It does not demonstrate a dairy intolerance or identify a gut bacterium.' } },
      { title: 'The gut–brain axis: real communication, limited shortcuts', text: 'The gut and nervous system communicate through neural, hormonal, immune and metabolic pathways. The microbiome—the community of microorganisms in and on the body—can participate in these interactions. Researchers study differences in microbial communities and metabolites in many conditions.', paragraphs: ['The existence of this communication does not prove that a particular stool profile caused autism or that changing it will improve communication. Diet, medicines, age, geography and sampling methods can affect findings. A difference between groups may be a cause, consequence or correlate. Describing butyrate as simply good and propionate as simply bad removes the biological context and does not create a usable treatment plan. Commercial testing needs evidence that its result improves a clinical decision, not just that it can measure something.'] },
      { title: 'What common diet labels leave out', text: 'A diet name can hide very different reasons for using it. A gluten-free diet for confirmed coeliac disease has a different purpose from a gluten-free diet promoted as an autism intervention. Some biomedical practitioners assign each elimination diet a set of observable “indicators” — red cheeks and ears or night sweats for a Feingold-style phenol restriction, pain or pressing on the genitals or eyes for a low-oxalate diet, a “spaced out” appearance and cravings for bread or dairy for an opioid-excess theory, sudden aggression after antibiotics for Clostridia-derived propionate. Those pairings come from clinical teaching within the biomedical community rather than from validated diagnostic studies; treating them as a bedside decision matrix risks turning an ordinary symptom into a label that justifies another purchase. NICE advises against exclusion diets for the core features of autism. That does not mean a separate food-related medical condition should be ignored.', table: { caption: 'Discuss the indication before the restriction', headings: ['Proposed approach', 'Question to ask', 'Concern to plan for'], rows: [['Gluten-free or casein-free', 'Is a specific condition being investigated or treated?', 'Removing staple foods can make an already narrow diet harder to balance.'], ['Low-oxalate or Feingold-style restriction', 'What diagnosis and evidence support this for this child?', 'A broad list of forbidden foods may reduce variety without treating the problem.'], ['Ketogenic diet', 'Is there a specialist-managed medical indication?', 'This requires medical and nutritional supervision, not a general autism trial.'], ['Probiotics or microbiome products', 'Which product, condition and outcome were actually studied?', 'Results from one strain or study cannot be assumed for every product.']] }, source: 'nice' },
      { title: 'Investigate coeliac disease before changing the evidence', text: 'If coeliac disease is suspected, discuss testing before starting a gluten-free diet. NIDDK explains that removing gluten before diagnostic testing can affect the results. The point is not that a child should continue a food during a medical emergency, but that a planned restriction can complicate an otherwise interpretable investigation.', paragraphs: ['Coeliac disease, wheat allergy and a reported food intolerance are different clinical questions. A family should know which is being considered and what testing is appropriate. Ask a dietitian or clinician how nutrients and energy will be replaced if a food group needs removal. In an Indian household, that discussion should use the foods the family actually eats—such as roti, rice, dal, curd or other staples—rather than an unrealistic imported menu.'], source: 'celiac' },
      { title: 'Use a brief diary without turning every meal into an experiment', text: 'For a few ordinary days, record meals accepted, drinks, bowel comfort, sleep and relevant changes in routine. Include the child’s own words or gestures. Record prescribed medicine changes, but do not deliberately change several foods or products at once to test a theory.', paragraphs: ['A diary can show that a question needs investigating; it cannot prove that one ingredient caused a behaviour. If a change is recommended, agree the purpose, nutritional safeguards and review point with the clinician. New pain, rash, urinary symptoms or worsening behaviour should not be dismissed as “oxalate dumping” or beneficial detox. Symptoms deserve assessment even when an online programme predicts them.'] },
      { title: 'A family should leave with a workable plan', text: 'Ask the team to separate immediate comfort, nutritional needs and longer-term feeding goals. Clarify which professional will manage each issue and what should prompt a call. A plan might address constipation first, assess growth and then work gradually on meal participation; the order should reflect the child’s needs.', paragraphs: ['The aim is a child who is more comfortable and better nourished, and a family that understands what to do next. Birth mode, early feeding choices and past antibiotic use should not be turned into a story of parental blame. Bring the history honestly, seek treatment for current symptoms and judge progress by meaningful changes rather than promises that a diet will reverse autism.'] },
    ],
  },
  'autism-treatment-evidence': {
    intro: ['A treatment advertisement may look scientific: a pathway diagram, several references, a percentage improvement and a doctor’s testimonial. Yet those elements can answer very different questions. A study showing a chemical effect in cells is not the same as a trial showing that children communicate more comfortably or sleep better.', 'Families should not need a research degree to ask useful questions. This guide offers a way to examine a claim, understand the type of evidence behind it and decide what needs clarification before committing time, money or a child’s energy. It applies to medicines, supplements, diets, therapy programmes and expensive test packages.'],
    takeaways: ['First define the actual treatment, population and outcome being claimed.', 'Compare study design, meaningful benefit, harms and uncertainty—not only a percentage.', 'A good care plan includes a goal, monitoring and a review or stopping decision.'],
    sections: [
      { title: 'Translate the promise into a question that can be tested', text: '“Improves brain health” is too vague to evaluate. Ask which intervention, for which children, compared with what, over what period, and measured how. A programme might claim to improve language, sleep, constipation and attention, but evidence for one outcome does not automatically support the others.', paragraphs: ['Then ask whether the outcome matters to the child. A laboratory value can change without daily life improving. Conversely, a practical accommodation may make school participation easier without changing a biological marker. Useful outcomes can include communicating a need, reducing painful bowel movements, sleeping adequately or taking part in an activity the child values. Define that goal before choosing a product.'] },
      { title: 'Recognize the kind of evidence being presented', text: 'Different study designs are useful for different questions. A laboratory experiment can explore a mechanism. An observational study can identify patterns. A controlled trial can help estimate whether an intervention changes an outcome. A systematic review can examine a body of research, but its conclusions still depend on the quality and relevance of the included studies.', table: { caption: 'What common evidence labels can and cannot do', headings: ['Evidence', 'Useful for', 'Main limitation'], rows: [['Mechanism or animal study', 'Understanding a possible biological process', 'Does not establish clinical benefit or safety in children'], ['Case report or testimonial', 'Describing an experience or unusual finding', 'Cannot reliably separate treatment effects from other changes'], ['Observational study', 'Finding associations and generating questions', 'Confounding can create an apparent relationship'], ['Randomized trial', 'Comparing outcomes under planned conditions', 'Small samples, short follow-up or poor measures can still limit confidence'], ['Systematic review or guideline', 'Considering a wider evidence base', 'A strong label cannot repair weak underlying studies']] } },
      { title: 'Read percentages with a denominator and a comparison', text: '“Sixty per cent improved” sounds impressive until you ask: sixty per cent of whom, how many people, and according to which measure? Was this a survey of people who completed a paid programme? Were families who stopped because of cost or side effects counted? How many improved without the intervention?', paragraphs: ['A percentage without these details can conceal more than it explains. Ask for absolute numbers and the comparison group’s result. Also distinguish statistical significance from clinical importance. A small average difference can be statistically detectable yet difficult to notice in daily life; a promising difference in a tiny study may be too uncertain to predict reliably.'], example: { title: 'Illustrative numbers, not a real study', text: 'Suppose 6 of 10 children improve with a programme and 5 of 10 improve with a comparison approach. Advertising “60% improved” hides the fact that the difference was one child in a very small sample. The example does not show the programme is useless; it shows why the percentage alone is not enough.' } },
      { title: 'Look for bias, missing information and changing evidence', text: 'Participants and researchers may have expectations about a treatment. Blinding can reduce some expectation effects; randomization can reduce systematic differences between groups. Neither guarantees a perfect study. Check whether the outcomes were chosen in advance, whether many different outcomes were tested and whether people who dropped out were accounted for.', paragraphs: ['Look for independent replication and conflicts of interest. A financial interest does not automatically make a study false, but it is relevant context. A paper can also be corrected or retracted. A reference list copied from an old slide deck may therefore no longer represent the current evidence. Ask for the actual paper and current guidance, not just a screenshot of a journal logo.'] },
      { title: 'Compare benefit with harms, burden and opportunity cost', text: 'An intervention can have side effects, but it can also impose a substantial burden without a dramatic medical complication. Repeated blood draws, strict food rules, long journeys and many hours of sessions affect children and families. Money spent on an unproven package may reduce access to supports with clearer value.', paragraphs: ['Ask what monitoring is needed and who pays for follow-up. Ask whether adverse events were actively recorded or merely not mentioned. “No side effects reported” is weaker than careful safety assessment, especially in a small or short study. The child’s distress, consent or assent where appropriate, fatigue and preferences should be part of the decision—not treated as obstacles to completing a programme.'] },
      { title: 'Apply the method to biomedical claims about autism', text: 'Biomedical autism discussions often describe oxidative stress, inflammatory signalling, methylation and the gut–brain axis, then connect them to interventions such as a “mito cocktail” of L-carnitine, CoQ10, creatine and B-vitamins, low-dose naltrexone, hyperbaric oxygen (HBOT) and ibuprofen for behavioural flares. They also quote improvement percentages for HBOT drawn from uncontrolled settings. The missing step is often evidence that the proposed intervention improves a meaningful outcome in the intended group of children in a comparison design. A biological pathway can make a hypothesis plausible without making a treatment effective, and a percentage quoted without a denominator, a comparison group or recorded harms cannot be compared with trial results.', paragraphs: ['NICE advises against hyperbaric oxygen and chelation for autism. Supplement combinations, low-dose naltrexone or anti-inflammatory medicines should not become home protocols because a mechanism sounds convincing — including when a protocol document presents them under labels such as “Tier 1 foundational”, “Tier 2 targeted biochemical support” or “Tier 3 advanced modulation”. Doses copied from teaching material are another risk: a figure written for an exam answer is not a prescription for your child, and some listed supplements interact with medicines or organs that need monitoring. Treating a confirmed deficiency, pain condition, epilepsy or other coexisting disorder is a distinct clinical decision. Ask the clinician to name that indication rather than presenting every intervention as treatment for autism itself.'], source: 'nice' },
      { title: 'Agree on a reviewable plan, not an open-ended promise', text: 'Before starting a recommended intervention, establish the baseline: what is happening now, in which settings, and how often? Choose a realistic outcome and a review date. Record other changes that may affect the result, including school support, sleep and illness. The plan should explain what to do if there is no benefit or if difficulties worsen.', paragraphs: ['Do not accept a rule that every improvement proves the treatment works while every deterioration proves detoxification or the need for more treatment. That makes the claim impossible to evaluate. A credible plan allows the possibility that the original explanation was wrong. It also distinguishes stopping an ineffective non-prescribed programme from changing a prescribed medicine, which should be discussed with the prescriber.'] },
      { title: 'Questions worth taking to the appointment', text: 'Ask: What exact problem are we treating? Which evidence applies to my child? What are the likely benefits and harms? What alternatives exist, including practical support or watchful review where appropriate? What is the full cost? How will we decide whether to continue?', paragraphs: ['A useful response should make the decision clearer rather than demand unquestioning trust. Families can be hopeful and still ask for evidence. They can also value their own observations without treating one experience as proof for everyone. The goal is to choose support that improves the child’s life, while staying willing to revise the plan as better information becomes available.'] },
    ],
  },
  'folinic-acid-and-autism': {
    intro: ['When a medicine is described as helping autistic children speak, families understandably want more than a dismissive yes or no. They want to know what was studied, whether their child resembles the participants, what improvement meant and whether the treatment is safe. News about folinic acid has often mixed those questions together.', 'Folinic acid is also called leucovorin. It has established medical uses, and research has investigated it in selected autistic children. However, a rare folate transport disorder, an antibody test and autism itself are not interchangeable diagnoses. Understanding those distinctions is essential before interpreting a headline or discussing treatment with a prescriber.'],
    takeaways: ['The 2026 US approval concerns a specific FOLR1-related disorder, not autism generally.', 'A small positive trial is a reason for further research, not a guarantee of benefit.', 'A treatment discussion should define the indication, outcome, risks and follow-up.'],
    sections: [
      { title: 'Folate, folic acid, methylfolate and folinic acid', text: 'Folate is the broad term for a family of vitamin B9 compounds involved in processes including cell growth and one-carbon metabolism. Folic acid, methylfolate and folinic acid are related but chemically distinct forms. They do not have identical roles or indications, and a product sold as one should not be substituted for another on the basis of a social-media comparison.', paragraphs: ['In particular, “folinic acid is always better than folic acid” is not a sound general rule. The relevant question is what condition is being treated and why a particular preparation is appropriate. A medicine used for a specific transport or metabolic disorder cannot automatically be recommended to everyone with language delay. Prescription decisions also need to account for the child’s other medicines and medical history.'] },
      { title: 'What cerebral folate transport deficiency means', text: 'The brain depends on regulated transport of nutrients. FOLR1 encodes folate receptor alpha, which has a role in folate transport. Disease-causing variants in this gene can produce a rare neurological disorder involving impaired delivery of folate to the central nervous system. This is a specialist diagnosis, not another name for autism.', paragraphs: ['In March 2026, the US FDA approved leucovorin for FOLR1-related cerebral folate transport deficiency. The specificity of that indication matters: the agency did not approve it as a general autism treatment. The US decision also does not establish the medicine’s current regulatory indication or availability in India. Families should ask a local prescriber to explain both the clinical rationale and the applicable regulatory context.'], source: 'fda' },
      { title: 'What an influential trial actually studied', text: 'A randomized, double-blind, placebo-controlled study reported by Frye and colleagues included 48 children with autism and language impairment and lasted 12 weeks. It found an advantage for folinic acid on a measure of verbal communication. The investigators also explored whether folate receptor autoantibody status related to response.', paragraphs: ['That is more informative than a testimonial because there was a comparison group and blinded treatment. It still leaves important questions. The sample was small, participants were selected, and 12 weeks cannot establish long-term outcomes. A change on a communication measure does not mean every participant developed fluent speech or that the treatment reversed autism. The study is a research signal to interpret alongside the wider evidence, not a prediction for an individual child.'], source: 'folinicTrial' },
      { title: 'Why promising research and routine care differ', text: 'Before a treatment becomes routine, clinicians need to know how reliably benefits are reproduced, which patients benefit, what harms occur and how outcomes compare with other options. A strong mechanism and an encouraging small trial can justify further research while still being insufficient for a general prescribing recommendation.', paragraphs: ['The AAP does not recommend routine leucovorin use for autistic children and identifies unresolved questions about patient selection, dosing, monitoring and longer-term safety. That position does not deny families’ experiences or make the topic unworthy of study. It means the evidence cannot yet support a dependable promise of benefit across autistic children. Advice should be updated when robust new evidence changes the picture.'], source: 'aap', table: { caption: 'Three claims that should not be treated as equivalent', headings: ['Claim', 'What it means', 'What it does not establish'], rows: [['A medicine treats a rare genetic disorder', 'There is an indication for a defined condition', 'That the same medicine benefits autism generally'], ['A small trial found improvement', 'A result deserves scientific attention', 'The size or likelihood of benefit for every child'], ['A family noticed a change', 'An experience worth discussing and documenting', 'That the medicine caused the change or is safe for others']] } },
      { title: 'What an antibody test can and cannot answer', text: 'Folate receptor alpha autoantibodies are discussed in the research because they may affect receptor function. Their presence is not the same as a confirmed disease-causing FOLR1 variant. Neither should be inferred simply from severe speech delay, irritability or a normal blood folate level.', paragraphs: ['If testing is proposed, ask what the assay measures, how well it has been validated for the intended clinical decision, and whether either result would change management. Ask how the finding relates to the child’s neurological assessment. A test result must be interpreted in context; it is not a stand-alone prescription. Families should not be led to believe that one commercial test provides a universal explanation for a child’s developmental profile.'], source: 'aapFaq' },
      { title: 'Make an individual treatment discussion specific', text: 'If a specialist considers leucovorin, the conversation should identify the condition being treated and distinguish established care from an off-label or uncertain use. Ask what functional outcome is realistic, how side effects will be monitored and when the plan will be reviewed. A careful clinician should be able to discuss uncertainty without promising a cure.', paragraphs: ['Bring a complete medicine and supplement list. Do not start, increase, substitute or stop treatment based on this article. If a child develops new agitation, sleep problems, gastrointestinal symptoms or another concerning change during a treatment, report it to the prescriber. A family should know whom to contact and what to do if symptoms become severe. A research protocol is not a home dosing guide.'], example: { title: 'Illustrative question for a prescriber', text: '“Are you treating a confirmed folate transport disorder or proposing a trial for language difficulties? Which evidence applies to my child, what would count as a meaningful benefit, and what findings would make you stop or reconsider?” This is a more useful discussion than asking whether the medicine is simply good or bad.' } },
      { title: 'Keep communication support moving forward', text: 'Medical questions should not put communication support on hold. A child may benefit from adults recognizing gestures, offering understandable choices, allowing processing time or working with a speech and language professional on an appropriate communication system. Success should include the ability to express needs and participate, not only the number of spoken words.', paragraphs: ['When reviewing any intervention, record changes in the child’s ordinary life: requesting help, communicating pain, enjoying an activity or managing frustration. Note other changes happening at the same time, such as school support or improved sleep. This makes a follow-up conversation more informative and helps avoid attributing every gain or setback to a single product. The family’s observations matter most when they are specific and interpreted alongside clinical evidence.'] },
    ],
  },
  'mitochondria-and-autism': {
    intro: ['“The cells are not making enough energy” sounds like a compelling explanation for fatigue, developmental difficulty or a child’s deterioration during illness. Mitochondria are important to health, and genuine mitochondrial diseases deserve specialist care. But the phrase “mitochondrial dysfunction” is also used loosely in discussions of autism, sometimes to justify extensive testing and supplement combinations.', 'This guide separates the normal biology, research findings and the investigation of a suspected medical disorder. The distinction is useful because it changes the question from “Which mitochondrial cocktail should we try?” to “What problem are we investigating, and what evidence would change the care plan?”'],
    takeaways: ['A research finding about energy metabolism is not an individual diagnosis.', 'The history, examination and pattern of organ involvement guide specialist testing.', 'Supplement lists should not be treated as universal autism protocols.'],
    sections: [
      { title: 'What mitochondria do', text: 'Mitochondria are structures inside cells that help convert the energy in nutrients into a form cells can use, particularly adenosine triphosphate, or ATP. The process involves linked chemical reactions, including the electron transport chain. Tissues with substantial energy needs, such as brain and muscle, can be affected when these systems are impaired.', paragraphs: ['Mitochondria also interact with cellular signalling and stress responses. That makes them relevant to many areas of research, not just autism. Finding a change in an energy-related marker in a study does not tell us whether that change caused the condition, followed another process, or reflects a subgroup of participants. A biological association needs to be distinguished from a clinically actionable diagnosis.'] },
      { title: 'Primary disease, secondary change and research terminology', text: 'Primary mitochondrial disease refers to disorders in which a defect in mitochondrial function is central to the disease process, often involving genetic causes. Secondary mitochondrial changes can occur in other illnesses or cellular stresses. Researchers may also use “dysfunction” to describe a particular experimental measurement without diagnosing a clinical mitochondrial disease.', paragraphs: ['These uses are not interchangeable. A study reporting altered mitochondrial activity in a sample cannot establish that every autistic child needs a metabolic work-up. Equally, an autism diagnosis should not prevent a clinician from investigating a separate neurological or systemic concern. The task is to identify a reason for testing, rather than using autism alone as either a reason to order everything or a reason to dismiss symptoms.'], table: { caption: 'Distinguishing three different statements', headings: ['Statement', 'Type of information', 'Next question'], rows: [['A laboratory study found altered energy metabolism', 'Research observation', 'Does it replicate and relate to meaningful clinical outcomes?'], ['A child has unexplained weakness and neurological changes', 'Clinical concern', 'Which assessment and referral are appropriate?'], ['A specialist identified a mitochondrial disorder', 'Individual diagnosis', 'What condition-specific monitoring and treatment are needed?']] } },
      { title: 'Which observations are useful to the clinician?', text: 'Describe actual changes in movement, endurance, growth, awareness and previously acquired abilities. “Fatigue” is more informative when explained: does the child stop walking after a short distance, become unusually sleepy, complain of pain, or avoid an activity that has become demanding? These are different observations.', paragraphs: ['Include whether concerns are persistent, episodic or linked with illness, and whether several body systems appear involved. Do not use a checklist to decide that constipation, toe-walking or sensory distress must have one metabolic cause. Such features are nonspecific. Sudden weakness, marked reduced awareness, a prolonged seizure or a seriously unwell child needs urgent medical care, not a trial of vitamins while waiting for test results.'], example: { title: 'Illustrative description', text: '“Over the last month, K. has needed to stop halfway up stairs previously managed without difficulty. We have also noticed a change in walking.” This gives a clinician a concrete change to assess. “Low mitochondrial energy” is a proposed explanation and should not replace the description.' } },
      { title: 'What lactate, pyruvate and related tests can tell us', text: 'Specialist investigations may include measurements such as lactate, pyruvate, creatine kinase, amino acids, acylcarnitines and urinary organic acids, selected for the clinical situation. These tests examine different aspects of metabolism or tissue involvement; they are not a single autism panel.', paragraphs: ['Collection and handling matter. Lactate can rise for reasons other than mitochondrial disease, including difficulties around obtaining a sample. The lactate-to-pyruvate ratio has interpretive limits and should not be treated as a simple score; the Mitochondrial Medicine Society emphasizes its usefulness in the appropriate setting, particularly when lactate is elevated. Normal screening results also do not exclude every mitochondrial disorder. Interpretation belongs with the clinical history and specialist expertise.'], source: 'mito' },
      { title: 'Genetic investigation is more than finding a gene name', text: 'Mitochondrial function depends on genes in both mitochondrial DNA and nuclear DNA. Consequently, investigation may involve different genetic approaches depending on the presentation and previous findings. The names POLG, MT-ND1 or SUCLA2 in a lecture are examples of biological relevance, not instructions to test every child for a fixed list.', paragraphs: ['Ask why a particular investigation has been selected and what an uncertain result would mean. Finding a variant is not always the same as finding the cause. A genetics or metabolic team may need to consider inheritance, the type of variant and whether it fits the child’s features. Families should receive an explanation of the implications rather than a report containing unexplained flags.'] },
      { title: 'Why a “mitochondrial cocktail” is not a general treatment plan', text: 'Some biomedical protocols list carnitine, coenzyme Q10, creatine and several vitamins. A substance’s role in metabolism does not establish that giving extra improves autism-related outcomes. Treatment for a confirmed disorder may be individualized, and evidence can differ between the ingredients and conditions.', paragraphs: ['For each proposed product, ask what is being treated, what evidence applies and what monitoring is needed. A combined package makes it difficult to know which ingredient caused a benefit or adverse effect. Dietary changes also deserve care: a ketogenic diet is a medical intervention in specific settings, not an ordinary family experiment for autism, aggression or unexplained tiredness. Do not copy doses from a slide deck.'], source: 'complementary' },
      { title: 'A practical plan while the medical question is investigated', text: 'Keep a concise record of episodes, functional changes and the child’s usual activities. Bring previous results so clinicians can interpret them in sequence and avoid unnecessary duplication. Ask who will coordinate referrals and how the family will receive and discuss results. If a specialist diagnoses a metabolic disorder, obtain that team’s individualized advice for illness and emergencies.', paragraphs: ['At the same time, continue addressing clearly identified communication, learning, sleep or comfort needs. A family does not have to choose between taking medical symptoms seriously and supporting everyday development. The most useful plan gives each concern an appropriate pathway and avoids making all progress depend on an unproven explanation about cellular energy.'] },
    ],
  },
  'developmental-regression': {
    intro: ['A parent may say, “She used to wave goodbye, and now she does not,” or “He had several words, but we have not heard them for weeks.” That experience is different from wondering when a new skill will appear. It can be frightening, especially when an online search immediately suggests a rare disease or a particular treatment.', 'The right response is to take the change seriously and describe it accurately. Developmental regression is a clinical concern, not a diagnosis in itself. The purpose of assessment is to work out what changed, whether there are urgent medical features, and which investigations or supports are appropriate. A timeline is useful; a theory chosen in advance can make that timeline harder to interpret.'],
    takeaways: ['Loss of an established skill needs prompt medical discussion.', 'Sudden neurological change or a seriously unwell child needs urgent care.', 'Record the timeline without assuming that an event preceding the change caused it.'],
    sections: [
      { title: 'What counts as a loss of skills?', text: 'Regression means a reduction or loss in an ability that was previously established. Examples might involve language, gestures, social interaction, walking, hand use or everyday self-care. The important detail is that the child had used the skill consistently, rather than performing it once under unusual circumstances.', paragraphs: ['A developmental plateau means progress has slowed or stopped without a clear loss. A situational difference means a child can still use a skill in some settings but not others. All three can warrant attention, but they suggest different questions. A child who speaks at home but becomes silent in a new classroom needs a different description from a child who has stopped using previously frequent words everywhere.'], table: { caption: 'Describing the concern accurately', headings: ['Pattern', 'Example', 'Question to clarify'], rows: [['Possible regression', 'Previously frequent words are no longer used anywhere', 'When were they last used consistently?'], ['Plateau', 'Existing words remain, but new communication is not developing', 'What has changed in demands or development?'], ['Context-dependent difficulty', 'Communication changes between home and school', 'Which setting, language or support makes a difference?']] } },
      { title: 'Decide whether the situation is an emergency', text: 'A child who is difficult to wake, has breathing difficulty, develops sudden weakness or cannot move normally, or has a prolonged seizure needs emergency medical care. Do not wait to complete a diary, obtain a developmental appointment or try a dietary change. If a seizure is occurring, protect the child from nearby hazards and seek urgent help; do not place anything in the mouth.', paragraphs: ['For a child who is otherwise stable but has lost previously acquired skills, contact a paediatric clinician promptly and explicitly use the phrase “loss of skills”. Explain the pace of the change and any associated illness, unusual movements, episodes of reduced awareness or change in walking. A routine question about speech delay may be triaged differently from a report of actual language loss.'] },
      { title: 'Build a short, factual timeline', text: 'Start with the last period when the skill was reliably present. Note the first change you noticed, whether it happened suddenly or gradually, and whether other people observed it. Include sleep, appetite, fever, medicine changes, pain and major changes in environment. Do not omit an event because it seems unrelated, but do not assign it a cause-and-effect relationship either.', paragraphs: ['Use existing messages, school notes or familiar videos to support recall if they are readily available. There is no need to reconstruct every day of the child’s life. When dates are uncertain, say “approximately two weeks” rather than inventing precision. Bring a current medicine and supplement list: the product name and formulation are more useful than “a tonic”.'], example: { title: 'Illustrative timeline', text: '“For about two months, A. used ‘water’ and ‘open’ independently most days. During the last three weeks we have heard neither at home or nursery. Pointing continues. Sleep has become fragmented. There was a fever shortly before we noticed the change, but we do not know whether it is related.” This separates observation from interpretation.' } },
      { title: 'What a clinician may need to distinguish', text: 'The assessment considers development alongside neurological and general health. Hearing changes, seizure-related concerns, pain, sleep disruption and other medical or developmental explanations may need attention. The clinician uses the age, type of skill loss, examination and associated features to choose the next step.', paragraphs: ['NICE distinguishes referral decisions involving language or social regression from those involving motor regression and older children. The practical message for a family is that the pattern matters: tell the clinician exactly which skills changed. Autism assessment may be part of the pathway, but it does not replace medical evaluation of new neurological symptoms. Not every child needs the same scans, blood tests or genetic investigations.'], source: 'diagnosis' },
      { title: 'Why regression does not prove mitochondrial disease', text: 'Some biomedical teaching presents regression after a fever, infection or vaccination as a “hallmark red flag” for mitochondrial fragility and describes it as evidence against a purely behavioural explanation. That framing overstates the evidence: the same material also acknowledges variability across biomarker studies and the intrinsic heterogeneity of the autism population. Regression is genuinely important and deserves prompt medical assessment, but illness follows a predictable course in every child, autistic or not, so timing alone cannot identify a cause. Many children have infections, sleep disruption or reduced activity around the time a concern becomes noticeable.', paragraphs: ['A specialist may consider metabolic or genetic investigation when the broader pattern supports it — for example, regression together with unexplained fatigue, loss of previously acquired motor skills, hypotonia, ataxia, seizures that are difficult to control, or failure to thrive despite adequate intake. An isolated symptom or a commercial panel cannot substitute for that judgement. Likewise, a normal initial test does not resolve every possible cause; the broader teaching itself points out that metabolic markers may only rise during illness or stress, so a normal baseline result does not settle the question either way. Ask what condition is being investigated, why the proposed test is useful and what the next step would be for either result. Avoid treating a supplement response as confirmation of a rare disease.'] },
      { title: 'Understanding events that happen close together', text: 'When a worrying change follows a memorable event, it is natural to connect them. A temporal association is worth recording, but it does not establish causation. The child’s age, other changes occurring at the same time and the expected background frequency of events all matter.', paragraphs: ['Vaccination is sometimes mentioned in this context. WHO’s December 2025 review found no causal link between vaccines and autism. That evidence should not be replaced by an inference from a single timeline. A family can report a health event, seek assessment of the child and discuss vaccination questions without assuming that the event explains an autism diagnosis.'], source: 'vaccines' },
      { title: 'Support the child while the assessment proceeds', text: 'Keep communication accessible and daily routines as understandable as possible. Offer familiar ways to request help or comfort, including gestures or pictures if these are already useful. Avoid repeatedly testing a missing skill throughout the day: this can add pressure without giving the clinician a clearer history.', paragraphs: ['Ask the care team what changes should trigger urgent reassessment, which appointments are being arranged and who will follow up results. If an intervention has been proposed, ask for its specific indication and review plan. New pain, rashes, marked agitation or worsening function should not be dismissed as “detox”. The priority is the child’s health and comfort, not completing an experimental protocol. Use the appointment planner to keep outstanding questions together.'] },
    ],
  },
  'mthfr-methylation-and-autism': {
    intro: ['MTHFR, SAMe, COMT, folate receptors: a genetic report or webinar can introduce a whole new vocabulary overnight. A colour-coded chart may then appear to offer a simple explanation for a child’s anxiety, speech delay or sensory needs—and a matching list of supplements. The attraction is understandable: a complicated developmental picture suddenly seems to have a mechanism and a solution.', 'The biology is real, but the treatment conclusion does not automatically follow. This article explains the pathways in ordinary language, separates common variants from rare metabolic disease, and shows how to assess whether a proposed test adds something useful to care. The aim is to make the science understandable without converting a research hypothesis into a prescription.'],
    takeaways: ['Common genetic variants are not the same as rare disease-causing variants.', 'A pathway diagram does not measure what is happening in an individual child’s brain.', 'Ask what a test result would change before purchasing a panel or supplement programme.'],
    sections: [
      { title: 'Methylation: what the word actually means', text: 'Methylation is the transfer of a small chemical unit called a methyl group. Different methylation reactions help cells regulate molecules and biological processes. DNA methylation is one aspect of gene regulation; it is not a simple switch that turns “autism genes” on or off. Different tissues and different sites on DNA can behave differently.', paragraphs: ['The folate and methionine cycles help supply the chemical materials used in these reactions. Folate is a B vitamin involved in one-carbon metabolism. Methionine can be converted into S-adenosylmethionine, usually shortened to SAMe, which donates methyl groups. After donation, further reactions lead to homocysteine. Homocysteine can be recycled toward methionine or directed through other pathways. These names describe normal metabolism, not an autism subtype.'] },
      { title: 'A useful map of the terminology', text: 'Biochemical teaching connects the folate cycle, methionine cycle and transsulfuration pathway. That is useful as a biochemical map, provided it is not mistaken for a diagnostic chart. In a living person these pathways interact with nutrition, enzymes, illness and many regulatory processes; a symptom cannot reveal the concentration of every intermediate.', table: { caption: 'Terms in a methylation discussion', headings: ['Term', 'Plain-language meaning', 'Important limit'], rows: [['MTHFR', 'An enzyme involved in producing a form of folate used in metabolism', 'A common variant does not by itself diagnose a developmental condition.'], ['Homocysteine', 'An intermediate in methionine metabolism', 'An abnormal result needs clinical context, not an automatic supplement stack.'], ['SAMe', 'A molecule that supplies methyl groups for many reactions', 'Its role in a pathway does not establish benefit from supplementation.'], ['Glutathione', 'A molecule involved in cellular antioxidant defence', 'A research finding about oxidative stress is not a universal treatment indication.']] }, paragraphs: ['A good explanation should specify which measurement is actually available, what that measurement reflects and what it does not. A diagram with arrows is a model of reactions. It is not a scan showing that a particular child has a blocked arrow.'] },
      { title: 'Common variants versus rare genetic disease', text: 'MTHFR C677T and A1298C are commonly discussed variants. Some variants can alter enzyme activity; their clinical importance depends on the variant and the wider context. Rare MTHFR-related metabolic disease is a different situation from finding a common polymorphism on a consumer report.', paragraphs: ['The distinction matters because the phrase “MTHFR mutation” is often used without qualification. Ask for the exact variant, the laboratory’s classification and whether the finding explains the clinical presentation. A report may identify a variant without establishing that it caused a child’s symptoms. Genetics professionals can help interpret uncertain or complex results, including whether further investigation is appropriate.'], source: 'genes' },
      { title: 'Why “overmethylated” and “undermethylated” charts overreach', text: 'Some clinical charts assign rigidity, anxiety, sleep difficulty or sensory sensitivity to opposing methylation categories, and state that undermethylation covers roughly 60–70% of autistic children while overmethylation covers 10–15%. Those percentages come from clinical teaching tradition rather than from a validated prevalence study, and the behaviours themselves are not specific biochemical measurements. The same child can have several of them for reasons involving communication demands, sleep, pain, attention, anxiety or the environment.', paragraphs: ['Nor can a reaction to a multivitamin establish a methylation diagnosis. The product may contain multiple ingredients, and timing alone does not identify the cause of a change. Record the reaction and discuss the actual formulation with a clinician. A treatment algorithm that moves directly from “red ears” or “rigid behaviour” to a biochemical label — and then to buying methyl donors or avoiding them — skips the work needed to establish what is happening.'], example: { title: 'Illustrative report interpretation', text: 'A report lists a common MTHFR variant and a supplement seller recommends five products. Before buying, a family asks: “Is there a diagnosed deficiency or metabolic condition? Which finding supports each product? Would the recommendation be different without this variant?” Those questions test the clinical usefulness of the report rather than disputing that the gene exists.' } },
      { title: 'COMT and MAO-A do not provide a personality prescription', text: 'COMT and MAO-A are involved in metabolism of signalling molecules. It is tempting to turn this into a simple story: a “slow” enzyme means a particular neurotransmitter is high, therefore a child must need or avoid a particular supplement. That story leaves out tissue differences, other enzymes, regulation and the complexity of a developing nervous system.', paragraphs: ['A common variant in one gene does not give a direct reading of brain dopamine or serotonin. It also does not replace standard prescribing assessment. If a report claims to predict which product will calm a child, ask for evidence that the specific test-guided strategy improves meaningful outcomes compared with ordinary clinical care. Evidence that a variant changes an enzyme in a laboratory is a different question.'] },
      { title: 'What to ask before ordering tests', text: 'Start with the clinical question. Is a clinician investigating an actual nutritional deficiency, an unexplained metabolic abnormality, a family history or a broader genetic cause of developmental difficulties? The question should determine the test. A large panel is not necessarily better than a focused investigation.', paragraphs: ['Ask how results will be explained, including a normal finding or a variant of uncertain significance. Confirm the full cost of interpretation and follow-up, not only the collection fee. Consider privacy too: genetic information can have implications for relatives, and a downloadable consumer report may contain more information than a school or therapy provider needs. Keep the decision connected to the child’s care rather than to the number of coloured flags in a report.'] },
      { title: 'Nutrition and medicines: a more useful conversation', text: 'A clinician can investigate a suspected deficiency and recommend treatment for it without adopting an unvalidated methylation category. Bring a list of foods regularly accepted, relevant symptoms, prescribed medicines and every supplement. Include labels: separate products often contain overlapping ingredients.', paragraphs: ['“Natural” and “vitamin” do not mean unlimited amounts are safe. Avoid adding methylfolate, methyl-B12, niacin, SAMe or combinations based on a chart. If a product is prescribed, ask what the target is, how benefit will be judged and when it will be reviewed. Folinic acid and rare folate transport disorders deserve a separate discussion; they are not interchangeable with a common MTHFR result or a general claim that a child needs methylation support.'], source: 'complementary' },
    ],
  },
  'autism-and-adhd-differences': {
    intro: [
      'A teacher says a child is constantly distracted. At home, the same child spends an hour explaining a favourite topic but becomes overwhelmed when dinner plans change. One relative suggests ADHD; another says autism. Both are trying to make sense of real observations, but neither observation settles the question.',
      'Autism and attention-deficit/hyperactivity disorder describe patterns of development, not personality types. The useful question is not whether a child is friendly, quiet, clever or energetic. It is how attention, communication, flexibility and self-regulation work for that child, what effort everyday activities require, and where support would make life easier. This guide explains the distinctions without turning them into a home diagnosis checklist.',
    ],
    takeaways: ['The same outward behaviour can have different explanations.', 'Autism and ADHD can coexist; assessment need not choose one and ignore the other.', 'A useful plan identifies strengths, barriers and supports across home and school.'],
    sections: [
      { title: 'What each diagnosis is trying to describe', text: 'Autism involves differences in social communication and interaction alongside restricted or repetitive patterns, interests or activities. Sensory responses and a strong need for predictability can be part of that picture. “Spectrum” does not mean a single line from a little autistic to very autistic: communication, learning, sensory comfort and everyday independence can differ greatly within one person.', paragraphs: ['ADHD concerns a persistent pattern of inattention and/or hyperactivity-impulsivity that interferes with functioning. It is not simply having a lot of energy or finding a dull lesson boring. Clinicians ask whether the pattern is greater than expected for developmental age, how long it has been present, and what it changes about everyday life. Neither diagnosis measures a child’s worth, kindness or potential.'], source: 'nimhAutism' },
      { title: 'Why similar behaviour can hide different needs', text: 'Consider a child who leaves a group activity. They may have lost track of a long instruction, found the room painfully noisy, misunderstood the game, felt anxious about an unpredictable turn, or needed a movement break. Several explanations can be true together. Labelling the action “poor attention” before asking about the context can lead to the wrong support.', paragraphs: ['The same applies to conversation. Interrupting may reflect difficulty waiting, uncertainty about when a turn begins, enthusiasm about a topic, or fear of forgetting what to say. A useful observation describes the situation and the child’s experience instead of assuming intention. The comparison below describes areas to explore, not rules that separate children into two neat groups.'], table: { caption: 'Questions that are more useful than stereotypes', headings: ['Area', 'What to observe', 'What it cannot establish alone'], rows: [['Attention', 'Starting, shifting and sustaining attention across different tasks', 'Intense focus on a preferred activity does not exclude ADHD.'], ['Social interaction', 'Understanding a conversation, taking turns and recovering from misunderstandings', 'Wanting friends does not exclude autism.'], ['Change and routine', 'What happens when plans change, and which preparation helps', 'Liking a routine is not by itself a diagnosis.'], ['Sensory experience', 'Noise, clothing, food textures, crowds and movement needs', 'A sensory preference does not identify one condition.']] } },
      { title: 'Executive function: the hidden work behind an ordinary task', text: 'Executive functions are the processes used to hold information in mind, begin a task, organize steps, inhibit an immediate response and switch to a new activity. “Get ready for school” may sound like one instruction to an adult, but it contains many decisions: find clothes, stop playing, remember the timetable, locate a notebook and estimate how much time remains.', paragraphs: ['A child may understand each step and still struggle to coordinate the sequence. Repeating the same broad instruction louder does not necessarily supply the missing structure. A short visual list, a clearly marked place for materials or one instruction at a time can make the demand more understandable. These are examples to discuss and adapt, not a substitute for identifying hearing, learning or other medical concerns.'], example: { title: 'Illustrative example: the missing schoolbag', text: 'Instead of “You never listen”, a parent records: “On three mornings, R. started dressing but returned to a toy before packing. With a two-step picture list and the bag beside the door, packing needed one reminder.” That observation shows both the difficulty and a possible support. It does not prove a diagnosis.' } },
      { title: 'What a careful assessment includes', text: 'An assessment usually brings together a developmental history, the child’s current functioning, information from caregivers and school, and clinical observation. Rating scales can structure information, but they do not replace a professional evaluation. Clinicians also consider sleep, anxiety, learning difficulties, hearing and other explanations for the concerns.', paragraphs: ['For ADHD, the history needs to establish symptoms beginning in childhood and difficulties across more than one setting, rather than relying on a single appointment. A quiet clinic visit does not reproduce a crowded classroom or a rushed morning. Equally, a difficult clinic visit does not describe the whole child. Bring examples of both easy and difficult situations and ask how conflicting reports will be understood.'], source: 'adhd' },
      { title: 'Co-occurrence and masking: why one label may not explain everything', text: 'A child can meet criteria for both autism and ADHD. For example, a need for predictable routines may coexist with difficulty organizing those routines. It is more useful to describe that combination than to argue that a child cannot have ADHD because they like sameness, or cannot be autistic because they seek social contact.', paragraphs: ['Some children copy peers, rehearse conversations or hold distress in during school. Adults may see apparent coping without seeing the effort involved. A collapse after returning home is worth describing, but it is not automatically proof of masking or a particular diagnosis. Ask about the whole day: recovery time, sensory load, unstructured breaks, friendships and the child’s own account. Support decisions should not depend only on how disruptive a child appears to other people.'], source: 'nimhAdhd' },
      { title: 'What support can look like after assessment', text: 'The plan should connect each recommendation to a real need. Communication support may help a child ask for clarification or express discomfort. Educational adjustments may make instructions and transitions easier to follow. Parent support can help adults respond consistently and reduce conflict. For ADHD, medication may be part of an individualized specialist plan, with discussion of benefits, side effects and monitoring.', paragraphs: ['A diagnosis should not result in an identical package for every family. Ask what each therapy is intended to improve, how the child will participate in choosing goals, and how progress will be reviewed. A goal such as “asks for a break using speech, a picture or a gesture” is clearer than “behaves normally”. Harmless repetitive movement or a different communication style does not automatically need to be suppressed.'], source: 'adhdCare' },
      { title: 'A practical way to prepare your first conversation', text: 'Write three short descriptions: a difficult situation, a successful situation and something your child enjoys. For each, note the setting, the demand, the support available and what happened next. Include languages used at home and school, any recent changes, sleep difficulties and previous reports. If you do not know an answer, leave it uncertain rather than guessing.', paragraphs: ['Then choose the question you most need answered. It might be “Why are written tasks so exhausting?”, “How can we make school arrival manageable?” or “Do these communication differences need assessment?” In Greater Noida, families can discuss the appropriate assessment pathway with Aasha. Ask about the scope of the appointment and which reports are useful; you do not need to buy a genetic or biochemical panel before having that conversation.'] },
    ],
  },
  'autism-screening-and-assessment': {
    intro: ['It often begins with an ordinary moment: a child does not respond as expected during play, a nursery teacher mentions communication, or a parent notices that development looks different from an older sibling’s. Searching online produces checklists, milestone charts and conflicting reassurance. What families usually need is a clear route from concern to understanding.', 'Screening is one part of that route. It can identify a reason to look more closely, but the most useful outcome is a description of the child’s strengths and needs, together with a practical plan. This article explains what happens before, during and after an autism assessment, including how to prepare without turning home life into a series of tests.'],
    takeaways: ['Monitoring, screening, diagnosis and support planning answer different questions.', 'A screening score is not a diagnosis or a measure of a child’s future.', 'Persistent concerns and loss of skills deserve attention even after a reassuring screen.'],
    sections: [
      { title: 'Four stages that are often confused', text: 'Developmental monitoring means noticing how a child communicates, plays, moves, learns and manages everyday activities over time. Screening uses a structured method to identify children who may need further evaluation. Diagnostic assessment investigates whether a pattern meets criteria for a condition. Support planning asks what will help the child participate now.', paragraphs: ['These stages are connected, but one does not do the job of all the others. A milestone checklist cannot establish a diagnosis. A diagnosis does not automatically specify the right number of therapy sessions. A child can also have a meaningful language, learning or sensory need without receiving the diagnosis a family first suspected. The assessment should help explain that outcome rather than simply issue a yes-or-no result.'], table: { caption: 'What each stage can tell a family', headings: ['Stage', 'Main question', 'Useful result'], rows: [['Monitoring', 'What is changing in everyday development?', 'Specific observations over time'], ['Screening', 'Is a closer look indicated?', 'Follow-up or referral guidance'], ['Assessment', 'How do the concerns fit the developmental and medical picture?', 'An explanation of findings and remaining uncertainty'], ['Planning', 'What support would make daily life easier?', 'Goals, responsibilities and a review date']] } },
      { title: 'When to raise a concern', text: 'Do not wait for a child to match every item on an internet list. Difficulties with communication, play, social interaction or everyday functioning can be discussed at a routine health visit. The AAP schedule described by CDC includes autism screening at 18 and 24 months, but that schedule is not a reason to postpone an earlier concern or dismiss one raised later.', paragraphs: ['Loss of a previously established skill is a different concern from learning a skill later than peers. If a child stops using words, gestures or movement skills they previously used consistently, describe that change promptly to a medical professional. Sudden illness, seizures or marked changes in awareness require medical attention rather than waiting for a developmental screening appointment.'], source: 'screening' },
      { title: 'Understanding M-CHAT-R/F without overreading the score', text: 'The Modified Checklist for Autism in Toddlers, Revised with Follow-Up is designed for toddlers aged 16–30 months. The follow-up component matters: it clarifies responses that may have been misunderstood or may reflect a different developmental concern. Use the official instructions and appropriate language version rather than an altered social-media quiz.', paragraphs: ['A result indicating increased likelihood means further evaluation is appropriate; it does not tell a parent that their child definitely has autism. A reassuring result is also not a lifetime clearance. Screening is a snapshot, and persistent concerns still deserve discussion. This website links to the tool owner rather than reproducing a questionnaire, changing its wording or presenting a local score as an independent diagnosis.'], source: 'mchat' },
      { title: 'What the assessment conversation may explore', text: 'The clinician may ask about pregnancy and birth, early development, communication, play, routines, sensory experiences, sleep, eating, health and family history. These questions are intended to understand the child, not to assign blame. A history of caesarean birth, formula feeding or an illness does not by itself explain why a child is autistic.', paragraphs: ['Assessment may involve observation and standardized tools, alongside information from caregivers and education settings. Hearing, language, learning and other health questions may need their own evaluation. Tools differ in purpose: an autism screening instrument, a diagnostic observation and a functional or disability assessment are not interchangeable. Ask which question each proposed tool addresses and how its result will be interpreted in your child’s context.'], source: 'diagnosis' },
      { title: 'Preparing useful examples in a multilingual family', text: 'Describe all the languages a child hears and uses, with whom they use them, and whether the concern appears in each language. Bring examples of gestures, expressions, understanding and communication beyond spoken words. If a child communicates comfortably with a grandparent but says little in school, explain the setting rather than reducing the difference to a single vocabulary count.', paragraphs: ['Useful examples are brief and ordinary: how the child asks for help, shares an interest, responds when a favourite activity ends or joins familiar play. Record what the adult did as well. You do not need to repeatedly prompt eye contact, remove favourite objects or create distress to “show the problem”. Ask permission before sharing recordings and keep a child’s videos out of public groups.'], example: { title: 'Illustrative observation to bring', text: '“At home, M. takes my hand to the kitchen and points to a cup. At nursery, staff say M. waits silently when thirsty. We would like help finding a communication method that works in both places.” This is more informative than “does not communicate” because it identifies an existing ability and a specific gap.' } },
      { title: 'Making sense of the report', text: 'A helpful report should explain the information considered, the findings, what remains uncertain and the recommended next steps. Ask for unfamiliar terms to be translated into everyday examples. A score may compare performance with a reference group, but it should not be treated as a prediction of everything a child will or will not achieve.', paragraphs: ['Before leaving, clarify who is responsible for each referral and when results will be reviewed. Ask whether recommendations are essential now, useful later or conditional on another finding. For families in India, a clinical diagnosis, school support discussion and formal disability certification may involve different processes. Confirm current requirements with the relevant service instead of assuming that one report automatically completes all three.'] },
      { title: 'Starting support while questions remain', text: 'Families can discuss practical communication support, predictable routines and school adjustments while assessment continues. The plan should match the difficulty observed. A visual choice board addresses a different need from a quieter classroom place or a hearing evaluation. It is reasonable to ask why a particular intervention is being suggested and what benefit would look like.', paragraphs: ['Keep the first plan manageable. Select one or two priorities, agree how the adults involved will help, and set a time to review. At Aasha, the appointment planner and developmental check-in can help organize your questions before discussing assessment. Their purpose is preparation: they do not replace validated tools, diagnose autism or require families to complete every field before seeking care.'] },
    ],
  },
};
